with cleaned as (select id, account_id, txn_time, merchant, is_flagged, case when amount >= 3600 then 'High' when amount >= 1600 then 'Medium' else 'Low' end as amount_tier from transactions where hour(txn_time) between 12 and 16), ranked as (select id, account_id, txn_time, is_flagged, amount_tier from (select *, rank() over (partition by merchant order by txn_time desc nulls first) as row_num from cleaned) ranked where row_num = 1), deduped as (select * from ranked qualify rank() over (partition by account_id order by txn_time nulls last) = 1), ranked_transactions as (select * from deduped qualify row_number() over (partition by account_id order by txn_time desc nulls first, id) = 1) select s.id, s.account_id, s.txn_time, s.amount_tier, (select max(x.amount) from transactions x where x.account_id = s.account_id) as max_transaction_amount from ranked_transactions s order by id desc nulls last limit 20
